"""Indonesian A1 foundation data for JUBA LISAN."""
from app.data._types import CurriculumUnit, GrammarExample, GrammarTopic, VocabularyEntry, VocabularySet, PhrasebookCategory, PhrasebookEntry, AssessmentQuestion

def _g(slug,title,summary,examples):
    return GrammarTopic(slug=slug,title=title,level="A1",category="core",summary=summary,explanation=summary,examples=[GrammarExample(text=x) for x in examples])
GRAMMAR_TOPICS=[_g(*x) for x in [["pronouns","Personal pronouns","Use saya, kamu, Anda, dia and kita/kami.",["Saya mahasiswa.","Dia teman saya."]],["nominal","Nominal sentences","Form identity sentences without a present copula.",["Saya guru.","Ini rumah saya."]],["negation","Negation","Use bukan for nominal predicates and tidak for verbs/adjectives.",["Ini bukan buku.","Saya tidak sibuk."]],["questions","Questions","Use apa, siapa, di mana, kapan and bagaimana.",["Ini apa?","Di mana stasiun?"]],["me-verbs","meN- verbs","Recognize common active verbs.",["Saya membaca buku.","Dia minum air."]],["location","Location","Use di for locations.",["Saya di rumah.","Buku di meja."]],["possessive","Possession","Express ownership with common noun + possessor patterns.",["Ini buku saya.","Itu teman dia."]],["requests","Requests","Use practical polite request patterns.",["Tolong ulangi.","Silakan duduk."]]]]
def _v(i,t,words):
    return VocabularySet(id=i,level="A1",topic=t,unit_ref="id-a1",words=[VocabularyEntry(word=w,pos=p,definition=d,example=e) for w,p,d,e in words])
VOCABULARY_SETS=[_v(*x) for x in [["greetings_a1","Greetings",[["halo","phrase","hello","Halo!"],["terima kasih","phrase","thank you","Terima kasih."],["nama","noun","name","Nama saya Rina."],["teman","noun","friend","Dia teman saya."]]],["family_a1","Family",[["ibu","noun","mother","Ibu saya di rumah."],["ayah","noun","father","Ayah saya bekerja."],["kakak","noun","older sibling","Kakak saya mahasiswa."],["adik","noun","younger sibling","Adik saya di rumah."]]],["home_a1","Home",[["rumah","noun","house","Rumah saya kecil."],["kamar","noun","room","Kamar saya bersih."],["buku","noun","book","Buku di meja."],["meja","noun","table","Buku di meja."]]],["daily_a1","Daily life",[["pagi","noun","morning","Saya bekerja pagi hari."],["kerja","noun","work","Saya kerja di kantor."],["belajar","verb","study","Saya belajar bahasa Indonesia."],["tidur","verb","sleep","Saya tidur malam."]]],["food_a1","Food",[["air","noun","water","Saya mau air."],["nasi","noun","rice","Saya makan nasi."],["teh","noun","tea","Saya minum teh."],["harga","noun","price","Berapa harganya?"]]],["places_a1","Places",[["jalan","noun","street","Jalan ini di mana?"],["stasiun","noun","station","Stasiun dekat."],["kanan","noun","right","Ke kanan."],["kiri","noun","left","Ke kiri."]]],["communication_a1","Communication",[["bantuan","noun","help","Saya perlu bantuan."],["tolong","adverb","please/help","Tolong ulangi."],["mengerti","verb","understand","Saya tidak mengerti."],["lagi","adverb","again","Tolong lagi."]]],["review_a1","Review",[["hari ini","phrase","today","Hari ini saya sibuk."],["besok","adverb","tomorrow","Saya datang besok."],["waktu","noun","time","Saya punya waktu."],["baik","adjective","good","Hari ini baik."]]]]]
def _p(i,s,items):
    return PhrasebookCategory(id=i,level="A1",situation=s,icon="💬",phrases=[PhrasebookEntry(text=t,context=c,register=r) for t,c,r in items])
PHRASEBOOK_CATEGORIES=[_p(*x) for x in [["greetings_a1","Greetings",[["Halo, apa kabar?","greeting","neutral"],["Nama saya Rina.","introducing yourself","neutral"]]],["shopping_a1","Shopping",[["Berapa harganya?","asking price","neutral"],["Saya mau ini.","requesting an item","neutral"]]],["directions_a1","Directions",[["Di mana stasiun?","asking location","neutral"],["Ke kanan, lalu lurus.","giving directions","neutral"]]],["help_a1","Help",[["Tolong bantu saya.","asking for help","polite"],["Saya tidak mengerti.","clarification","neutral"]]]]]
CURRICULUM={"A1":[CurriculumUnit(id=f"id-a1-unit-{i}",level="A1",unit_number=i,title=t,grammar_points=g,vocabulary_set_ids=v,lesson_types=["grammar","vocabulary","reading","listening","speaking","writing","review"],competency_checklist=[c1,c2],default_weeks=2) for i,(t,g,v,c1,c2) in enumerate([["Salam dan perkenalan",["pronouns","nominal"],["greetings_a1"],"Introduce yourself","Exchange greetings"],["Keluarga",["possessive","nominal"],["family_a1"],"Describe family","Ask about relatives"],["Rumah",["location","possessive"],["home_a1"],"Describe a room","Locate objects"],["Kehidupan sehari-hari",["me-verbs","negation"],["daily_a1"],"Talk about routines","State negatives"],["Makanan",["questions","negation"],["food_a1"],"Buy food","Ask prices"],["Tempat",["location","questions"],["places_a1"],"Ask directions","Give directions"],["Komunikasi",["requests","questions"],["communication_a1"],"Ask for help","Clarify meaning"],["Ulangan A1",["pronouns","negation","me-verbs"],["review_a1"],"Review A1","Handle familiar exchanges"]],1)]}
for level in ["A2","B1","B2","C1","C2"]:
    CURRICULUM[level]=[CurriculumUnit(id=f"id-{level.lower()}-foundation",level=level,unit_number=1,title=f"Indonesian {level}",grammar_points=["review A1"],vocabulary_set_ids=["review_a1"],lesson_types=["grammar","vocabulary","reading","writing","review"],competency_checklist=[f"Build {level} communication"],default_weeks=2)]
ASSESSMENT_BANK=[AssessmentQuestion(id=f"id-a1-{i:03}",skill=s,difficulty="A1",question=q,options=o,correct=c) for i,(s,q,o,c) in enumerate([["vocabulary","What does halo mean?",["hello","thanks","station","water"],"hello"],["vocabulary","What does terima kasih mean?",["thank you","goodbye","food","house"],"thank you"],["grammar","Choose 'This is not a book'.",["Ini bukan buku.","Ini buku.","Buku di meja.","Saya membaca."],"Ini bukan buku."],["grammar","Which means 'I am at home'?",["Saya di rumah.","Saya bukan rumah.","Rumah saya buku.","Saya rumah."],"Saya di rumah."],["vocabulary","What is ibu?",["mother","father","friend","sibling"],"mother"],["grammar","Which asks where the station is?",["Di mana stasiun?","Siapa stasiun?","Apa stasiun?","Kapan stasiun?"],"Di mana stasiun?"],["vocabulary","What does harga mean?",["price","help","morning","name"],"price"],["reading","Buku di meja. Where is the book?",["On the table","At the station","In the street","At work"],"On the table"],["communication","Which is a request for help?",["Tolong bantu saya.","Halo.","Besok datang.","Ini rumah."],"Tolong bantu saya."],["communication","What can you say if you do not understand?",["Saya tidak mengerti.","Terima kasih.","Nama saya Rina.","Ke kanan."],"Saya tidak mengerti."]],1)]
